import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react'
import type { TenantManifest } from '@/entities/tenant/types'
import { defaultTenantManifest } from '@/app/config/manifest.default'
import { tenantsService } from '@/integrations/supabase/tenants'

type TenantContextValue = {
  manifest: TenantManifest | null
  isLoading: boolean
  error: string | null
  activeSlug: string
  setActiveSlug: (slug: string) => void
  term: (key: string) => string
  hasFeature: (flag: string) => boolean
  hasApp: (appId: string) => boolean
  hasAdminModule: (moduleId: string) => boolean
}

const ENV_SLUG = import.meta.env.VITE_TENANT_SLUG ?? defaultTenantManifest.slug
const STORAGE_KEY = 'activeTenantSlug'

const TenantContext = createContext<TenantContextValue>({
  manifest: null,
  isLoading: true,
  error: null,
  activeSlug: ENV_SLUG,
  setActiveSlug: () => {},
  term: (k) => k,
  hasFeature: () => false,
  hasApp: () => false,
  hasAdminModule: () => false,
})

export function useTenant() {
  return useContext(TenantContext)
}

function readInitialSlug(): string {
  if (typeof window === 'undefined') return ENV_SLUG
  return window.localStorage.getItem(STORAGE_KEY) || ENV_SLUG
}

export function TenantProvider({ children }: { children: ReactNode }) {
  const [manifest, setManifest] = useState<TenantManifest | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [activeSlug, setActiveSlugState] = useState<string>(readInitialSlug)

  useEffect(() => {
    setIsLoading(true)
    setError(null)
    ;(async () => {
      try {
        const m = await tenantsService.fetchManifest(activeSlug)
        if (!m) {
          setManifest(null)
          setError(`Tenant '${activeSlug}' is not provisioned`)
        } else {
          setManifest(m)
        }
      } catch (e) {
        setManifest(null)
        setError(e instanceof Error ? e.message : String(e))
      } finally {
        setIsLoading(false)
      }
    })()
  }, [activeSlug])


  const setActiveSlug = useCallback((slug: string) => {
    if (typeof window !== 'undefined') {
      if (slug && slug !== ENV_SLUG) window.localStorage.setItem(STORAGE_KEY, slug)
      else window.localStorage.removeItem(STORAGE_KEY)
    }
    setActiveSlugState(slug)
  }, [])

  const term = (key: string) => manifest?.branding.terminology?.[key] ?? key
  const hasFeature = (flag: string) => manifest?.featureFlags.includes(flag) ?? false
  const hasApp = (appId: string) => manifest?.enabledApps.includes(appId) ?? false
  const hasAdminModule = (moduleId: string) => manifest?.enabledAdminModules.includes(moduleId) ?? false

  return (
    <TenantContext.Provider value={{ manifest, isLoading, error, activeSlug, setActiveSlug, term, hasFeature, hasApp, hasAdminModule }}>
      {children}
    </TenantContext.Provider>
  )
}
